<?php require_once __DIR__.'/database.php';class DashboardModel{private PDO $db;function __construct(){$this->db=Database::get();}function count($t){if(!in_array($t,['users','doctors','departments','appointments'],true))return 0;return (int)$this->db->query("SELECT COUNT(*) FROM $t")->fetchColumn();}function patient($id){$s=$this->db->prepare("SELECT COUNT(*) total,SUM(status='pending') pending,SUM(status='completed') completed FROM appointments WHERE patient_id=?");$s->execute([$id]);return $s->fetch();}function doctor($id){$s=$this->db->prepare("SELECT COUNT(*) total,SUM(appointment_date=CURDATE() AND status IN('pending','checked-in')) today,SUM(status='completed') completed FROM appointments WHERE doctor_id=?");$s->execute([$id]);return $s->fetch();}}
?>